#!/usr/bin/env bash
# Question 14: Kustomization does not build. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/kustomize/${Q14_APP}-app
mkdir -p /opt/course/kustomize/${Q14_APP}-app
chown -R ubuntu:ubuntu /opt/course
mkdir -p /opt/course/kustomize/${Q14_APP}-app
cat > /opt/course/kustomize/${Q14_APP}-app/namespace.yaml <<EOF
apiVersion: v1
kind: Namespace
metadata:
  name: ${Q14_APP}-dev
EOF
cat > /opt/course/kustomize/${Q14_APP}-app/deployment.yaml <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q14_APP}
spec:
  replicas: 1
  selector:
    matchLabels: { app: ${Q14_APP} }
  template:
    metadata:
      labels: { app: ${Q14_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          envFrom:
            - configMapRef: { name: ${Q14_APP}-settings }
EOF
cat > /opt/course/kustomize/${Q14_APP}-app/config-map.yaml <<EOF
apiVersion: v1
kind: ConfigMap
metadata:
  name: ${Q14_APP}-settings
data:
  MODE: dev
EOF
cat > /opt/course/kustomize/${Q14_APP}-app/replicas.yaml <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q14_APP}
spec:
  replicas: 2
EOF
# Two of four mistakes, rolled here: every pair holds at least one that stops the build.
api=kustomize.config.k8s.io/v1beta1 res=config-map.yaml ppath=replicas.yaml target=${Q14_APP}
for e in $(shuf -e resource-file patch-file api-version patch-target -n 2); do
  case "$e" in
    resource-file) res=configmap.yaml ;;
    patch-file) ppath=replica-count.yaml ;;
    api-version) api=kustomize.config.k8s.io/v1 ;;
    patch-target) target=${Q14_APP}-server ;;
  esac
done
cat > /opt/course/kustomize/${Q14_APP}-app/kustomization.yaml <<EOF
apiVersion: $api
kind: Kustomization
namespace: ${Q14_APP}-dev
resources:
  - namespace.yaml
  - deployment.yaml
  - $res
patches:
  - path: $ppath
    target:
      kind: Deployment
      name: $target
EOF
chown -R ubuntu:ubuntu /opt/course
sha256sum /opt/course/kustomize/${Q14_APP}-app/namespace.yaml /opt/course/kustomize/${Q14_APP}-app/deployment.yaml /opt/course/kustomize/${Q14_APP}-app/config-map.yaml /opt/course/kustomize/${Q14_APP}-app/replicas.yaml > /root/.cka-kustomize-${Q14_APP}-app.sums
kubectl delete namespace "${Q14_APP}-dev" --ignore-not-found --wait=true >/dev/null
! kubectl kustomize /opt/course/kustomize/${Q14_APP}-app >/dev/null 2>&1 || { echo "the kustomization still builds" >&2; exit 1; }
: "${Q14_APP}"
